// Shared brand tokens and small presentational atoms, ported from nbd_education_platform.jsx (the shell prototype).
// Real NBD brand colors: #a8cb63 (light green), #5e8f1e (deep green), #666666 (grey).
export const navy = { 50: "#f2f7e9", 100: "#e3edc8", 300: "#c3dd8f", 500: "#a8cb63", 700: "#5e8f1e", 900: "#333333" };
export const gold = "#5e8f1e";
export const cream = "#faf9f6";
export const grey = "#666666";
export const WORDMARK_SRC = "data:image/png;base64,";

export function Badge({ children, tone = "navy" }) {
  const tones = {
    navy: { background: navy[100], color: navy[700] },
    gold: { background: "#eef5e6", color: "#4d6b2c" },
    muted: { background: "#efe9e3", color: "#6b6155" },
  };
  return <span style={{ ...tones[tone], fontSize: 14, fontWeight: 500, padding: "3px 10px", borderRadius: 999 }}>{children}</span>;
}

export function StatCard({ label, value, icon: Icon }) {
  return (
    <div style={{ background: "#fff", border: "1px solid #e4dfd6", borderRadius: 12, padding: "16px 18px", flex: 1, minWidth: 140 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 8, color: "#8a8074", fontSize: 15, marginBottom: 8 }}>
        <Icon size={15} /> {label}
      </div>
      <div style={{ fontSize: 28, fontWeight: 600, color: navy[900] }}>{value}</div>
    </div>
  );
}

// Crops the icon mark out of the full wordmark image using plain CSS
// positioning rather than a separately-cropped file — the mark sits inside
// a known region of WORDMARK_SRC (2134x834 source), so it's scaled up and
// shifted into a fixed, clipped box to isolate just that region.
export function Logo({ size = 40 }) {
  const sourceW = 2134;
  const sourceH = 834;
  const cropW = 450;
  const cropH = 450;
  const cropLeft = 727;
  const cropTop = 190;
  const scale = size / cropH;
  return (
    <div style={{ height: size, width: size, overflow: "hidden", position: "relative", flexShrink: 0 }}>
      <img
        src={WORDMARK_SRC}
        alt="National Beauty Distribution"
        style={{
          position: "absolute",
          height: sourceH * scale,
          width: sourceW * scale,
          left: -cropLeft * scale,
          top: -cropTop * scale,
          maxWidth: "none",
        }}
      />
    </div>
  );
}

export function AuthHero({ eyebrow, headline, subtitle }) {
  return (
    <div
      style={{
        background: "linear-gradient(160deg, #1c1c1c 0%, #262626 55%, #2c3420 100%)",
        padding: "clamp(48px, 8vw, 96px) 24px clamp(56px, 9vw, 108px)",
        textAlign: "center",
      }}
    >
      <div style={{ display: "flex", justifyContent: "center", marginBottom: 40 }}>
        <img src={WORDMARK_SRC} alt="National Beauty Distribution" style={{ height: "clamp(64px, 11vw, 120px)", filter: "brightness(0) invert(1)" }} />
      </div>
      <div style={{ fontSize: 15, fontWeight: 700, letterSpacing: 3, textTransform: "uppercase", color: navy[500], marginBottom: 18 }}>
        {eyebrow}
      </div>
      <h1
        style={{
          fontFamily: "'Lato', -apple-system, sans-serif",
          fontWeight: 300,
          fontSize: "clamp(36px, 6vw, 64px)",
          color: "#fff",
          margin: "0 0 20px",
          lineHeight: 1.08,
        }}
      >
        {headline}
      </h1>
      <div
        style={{
          fontSize: "clamp(12px, 1.6vw, 15px)",
          letterSpacing: 2,
          textTransform: "uppercase",
          color: "#c9c9c9",
          maxWidth: 640,
          margin: "0 auto",
          lineHeight: 1.7,
        }}
      >
        {subtitle}
      </div>
    </div>
  );
}
